-- GASP dataset user (snapshot; User). snapshot rows on month starts, month ends and the period bounds shifted back by one, three, six and twelve months
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.user (
  activation_date DATE,
  core_features_adopted BOOLEAN,
  customer_id VARCHAR(1000),
  first_use_date DATE,
  last_active_date DATE,
  signup_date DATE,
  snapshot_date DATE,
  user_id VARCHAR(1000),
  user_status VARCHAR(1000)
);
